import React, { useState } from 'react';
import { 
  Bell, Mail, Smartphone, Globe, 
  MessageSquare, Calendar, AlertTriangle, TrendingUp
} from 'lucide-react';

const NotificationSettings = ({ expanded = false }) => {
  const [notifications, setNotifications] = useState({
    email: {
      marketing: true,
      security: true,
      updates: false,
      weekly: true
    },
    push: {
      mentions: true,
      replies: false,
      follows: true,
      likes: false
    },
    sms: {
      alerts: false,
      reminders: true,
      promotions: false
    }
  });

  const toggleNotification = (type, key) => {
    setNotifications(prev => ({
      ...prev,
      [type]: {
        ...prev[type],
        [key]: !prev[type][key]
      }
    }));
  };

  const notificationGroups = [
    {
      title: 'Notifications par email',
      icon: <Mail className="h-5 w-5 text-blue-500" />,
      type: 'email',
      items: [
        { key: 'marketing', label: 'Marketing et promotions', description: 'Offres spéciales et nouveaux produits' },
        { key: 'security', label: 'Alertes de sécurité', description: 'Connexions suspectes et changements' },
        { key: 'updates', label: 'Mises à jour produit', description: 'Nouvelles fonctionnalités et améliorations' },
        { key: 'weekly', label: 'Rapports hebdomadaires', description: 'Résumé de vos activités' }
      ]
    },
    {
      title: 'Notifications push',
      icon: <Smartphone className="h-5 w-5 text-purple-500" />,
      type: 'push',
      items: [
        { key: 'mentions', label: 'Mentions', description: 'Quand quelqu\'un vous mentionne' },
        { key: 'replies', label: 'Réponses', description: 'Réponses à vos commentaires' },
        { key: 'follows', label: 'Nouveaux abonnés', description: 'Quand quelqu\'un vous suit' },
        { key: 'likes', label: 'Likes', description: 'Quelqu\'un aime votre contenu' }
      ]
    },
    {
      title: 'Notifications SMS',
      icon: <MessageSquare className="h-5 w-5 text-emerald-500" />,
      type: 'sms',
      items: [
        { key: 'alerts', label: 'Alertes urgentes', description: 'Notifications critiques importantes' },
        { key: 'reminders', label: 'Rappels', description: 'Rappels de rendez-vous et tâches' },
        { key: 'promotions', label: 'Promotions', description: 'Offres spéciales par SMS' }
      ]
    }
  ];

  return (
    <div className="bg-gradient-to-br from-white to-white/80 dark:from-neutral-900 dark:to-neutral-900/80 backdrop-blur-xl rounded-3xl shadow-xl border border-white/40 dark:border-neutral-800/60 p-6">
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center space-x-3">
          <div className="h-12 w-12 rounded-2xl bg-gradient-to-r from-blue-500 to-cyan-400 flex items-center justify-center">
            <Bell className="h-6 w-6 text-white" />
          </div>
          <div>
            <h3 className="text-lg font-bold text-neutral-900 dark:text-white">Préférences de notification</h3>
            <p className="text-sm text-neutral-600 dark:text-neutral-400">Contrôlez vos notifications</p>
          </div>
        </div>
        <div className="flex items-center space-x-2">
          <button className="px-4 py-2 rounded-xl border border-neutral-200 dark:border-neutral-700 text-neutral-700 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors">
            Désactiver tout
          </button>
          <button className="px-4 py-2 rounded-xl bg-gradient-to-r from-primary-500 to-secondary-500 text-white hover:shadow-lg hover:shadow-primary-500/25 transition-all duration-300">
            Sauvegarder
          </button>
        </div>
      </div>

      {/* Notification Groups */}
      <div className="space-y-6">
        {notificationGroups.map((group, index) => (
          <div key={index} className="animate-fadeIn" style={{ animationDelay: `${index * 100}ms` }}>
            <div className="flex items-center space-x-2 mb-4">
              {group.icon}
              <h4 className="font-semibold text-neutral-900 dark:text-white">{group.title}</h4>
            </div>

            <div className="space-y-3">
              {group.items.map((item) => (
                <div 
                  key={item.key}
                  className="flex items-center justify-between p-4 rounded-2xl bg-neutral-50 dark:bg-neutral-800/30 hover:bg-neutral-100 dark:hover:bg-neutral-800/50 transition-colors group"
                >
                  <div className="flex-1">
                    <p className="font-medium text-neutral-900 dark:text-white">{item.label}</p>
                    <p className="text-sm text-neutral-600 dark:text-neutral-400">{item.description}</p>
                  </div>
                  <button
                    onClick={() => toggleNotification(group.type, item.key)}
                    className={`relative inline-flex h-7 w-12 items-center rounded-full transition-all duration-300 ${
                      notifications[group.type][item.key]
                        ? 'bg-gradient-to-r from-primary-500 to-secondary-500'
                        : 'bg-neutral-300 dark:bg-neutral-700'
                    } group-hover:scale-105`}
                  >
                    <span className={`inline-block h-5 w-5 transform rounded-full bg-white transition ${
                      notifications[group.type][item.key] ? 'translate-x-6' : 'translate-x-1'
                    }`} />
                  </button>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>

      {/* Notification Schedule */}
      {expanded && (
        <div className="mt-8 pt-8 border-t border-neutral-200 dark:border-neutral-800">
          <h4 className="font-semibold text-neutral-900 dark:text-white mb-4 flex items-center">
            <Calendar className="h-5 w-5 text-amber-500 mr-2" />
            Planning des notifications
          </h4>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="p-4 rounded-2xl bg-gradient-to-br from-blue-50 to-blue-100/30 dark:from-blue-900/10 dark:to-blue-800/5">
              <div className="flex items-center justify-between mb-2">
                <span className="text-sm font-medium text-neutral-900 dark:text-white">Heure de début</span>
                <span className="text-sm font-bold text-blue-600 dark:text-blue-400">09:00</span>
              </div>
              <p className="text-xs text-neutral-600 dark:text-neutral-400">Début des notifications quotidiennes</p>
            </div>
            <div className="p-4 rounded-2xl bg-gradient-to-br from-purple-50 to-purple-100/30 dark:from-purple-900/10 dark:to-purple-800/5">
              <div className="flex items-center justify-between mb-2">
                <span className="text-sm font-medium text-neutral-900 dark:text-white">Heure de fin</span>
                <span className="text-sm font-bold text-purple-600 dark:text-purple-400">20:00</span>
              </div>
              <p className="text-xs text-neutral-600 dark:text-neutral-400">Fin des notifications quotidiennes</p>
            </div>
            <div className="p-4 rounded-2xl bg-gradient-to-br from-emerald-50 to-emerald-100/30 dark:from-emerald-900/10 dark:to-emerald-800/5">
              <div className="flex items-center justify-between mb-2">
                <span className="text-sm font-medium text-neutral-900 dark:text-white">Mode ne pas déranger</span>
                <span className="text-xs font-medium px-2 py-1 bg-amber-500/10 text-amber-600 dark:text-amber-400 rounded-full">
                  Actif
                </span>
              </div>
              <p className="text-xs text-neutral-600 dark:text-neutral-400">Silencieux pendant les réunions</p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default NotificationSettings;
